'use strict'

import { SPRITE_TEXT_COLOR_WHITE, TILE_HEIGHT, TILE_WIDTH } from '../constant'
import textManager from '../service/text-manager'
import hitboxManager from '../service/hitbox-manager'

class Item {
  constructor (name, column, line, x, y, width, height, sprite, price) {
    this.name = name
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.width = width
    this.height = height
    this.sprite = sprite
    this.price = price
    this.hitbox = hitboxManager.compute({ x, y, width, height })
    this.enabled = true
  }

  init () {
    this.sprite.start()
    this.enabled = true
  }

  reset () {
    this.sprite.stop()
  }

  // At its place on the map, or elsewhere (in the top menu once picked)
  draw (context, x = this.x, y = this.y) {
    if (!this.enabled) {
      return
    }

    this.sprite.draw(context, x, y, this.width, this.height)

    if (this.price) {
      textManager.draw(context, this.price.toString(), SPRITE_TEXT_COLOR_WHITE, this.x - 0.5 * TILE_WIDTH, this.y + 1.5 * TILE_HEIGHT, TILE_WIDTH * 1.5, TILE_HEIGHT, 'right')
    }
  }

  clone () {
    return new Item(this.name, this.column, this.line, this.x, this.y, this.width, this.height, this.sprite, this.price)
  }
}

export { Item }
